import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DATA-LIST.md","filePath":"manual-en/DATA-LIST.md","lastUpdated":1785684581000}'),n={name:"manual-en/DATA-LIST.md"};function r(i,t,s,T,c,A){return e(),d("div",null,[...t[0]||(t[0]=[o('<h3 id="_8-5-data-list" tabindex="-1">8.5 DATA LIST <a class="header-anchor" href="#_8-5-data-list" aria-label="Permalink to &quot;8.5 DATA LIST&quot;">​</a></h3><p>Used to read text or binary data, <code>DATA LIST</code> is the most fundamental data-reading command. Even the more sophisticated input methods use <code>DATA LIST</code> commands as a building block. Understanding <code>DATA LIST</code> is important to understanding how to use PSPP to read your data files.</p><p>There are two major variants of <code>DATA LIST</code>, which are fixed format and free format. In addition, free format has a minor variant, list format, which is discussed in terms of its differences from vanilla free format.</p><p>Each form of <code>DATA LIST</code> is described in detail below.</p><p>See <a href="./GET-DATA">GET DATA</a>, for a command that offers a few enhancements over DATA LIST and that may be substituted for DATA LIST in many situations.</p><table tabindex="0"><thead><tr><th>• DATA LIST FIXED</th><th></th><th>Fixed columnar locations for data.</th></tr></thead><tbody><tr><td>• DATA LIST FREE</td><td></td><td>Any spacing you like.</td></tr><tr><td>• DATA LIST LIST</td><td></td><td>Each case must be on a single line.</td></tr></tbody></table>',6)])])}const f=a(n,[["render",r]]);export{l as __pageData,f as default};
